import type { BlogPost } from "./blog";

type Draft = Omit<BlogPost, "markdown"> & {
  intro: string;
  sections: Array<[string, string]>;
};

function makeMarkdown(draft: Draft): string {
  return [
    `# ${draft.title}`,
    draft.intro,
    ...draft.sections.flatMap(([heading, body]) => [`## ${heading}`, body]),
  ].join("\n\n");
}

